// Real logos of assets, networks, derivative venues and swap providers — self-hosted (src/logos/, shipped as one lazily
// loaded, hashed, immutable chunk: src/icons-data.ts), never fetched from a third party. The typed map is generated by
// apps/web/scripts/gen-icons.mts from src/logos/icons.json; provenance and licences: src/logos/SOURCES.md.
//
// What the owner must be able to tell apart at a glance, because confusing them costs money:
//   · the same asset on two networks        → the asset's logo + a badge with the NETWORK's logo (bottom-right);
//   · a pegged / bridged / wrapped copy     → its issuer's own mark when one exists (cbBTC, tBTC, WBTC, USDT0…), otherwise the
//                                             underlying's logo with a badge that is ALWAYS shown (USDC.e, BTC.b, BTCB, WBNB…);
//   · a coin on its home network            → no badge (BTC on Bitcoin, ETH on Ethereum): the badge would repeat the logo.
// A symbol the registry does not know (a perpetual's base asset, say) keeps a generic letter disc: no logo is ever invented.
import { useState, useSyncExternalStore } from 'react';
import { ASSET_ICONS, NETWORK_ICONS, PROVIDER_ICONS, VENUE_ICONS, type IconDef } from './icons.gen';

// the files arrive once, in their own chunk; until then a logo shows its skeleton (never the generic fallback)
let dataUrl: ((file: string) => string | null) | null = null; const waiting = new Set<() => void>();
void import('./icons-data').then((m) => { dataUrl = m.dataUrl; for (const f of waiting) f(); }, () => { dataUrl = () => null; for (const f of waiting) f(); });
const subscribe = (f: () => void) => { waiting.add(f); return () => { waiting.delete(f); }; };
const useIconsReady = () => useSyncExternalStore(subscribe, () => dataUrl !== null, () => false);

/** Does this asset on this network need the network badge? (exported for tests) */
export function needsBadge(sym: string, net: string | undefined): boolean {
  if (!net) return false;
  const d = ASSET_ICONS[sym];
  return !d || !!d.of || d.home !== net;
}

function Plate({ def, size, letters, title }: { def: IconDef | undefined; size: number; letters: string; title?: string }) {
  const ready = useIconsReady(); const [state, setState] = useState<'wait' | 'ok' | 'bad'>('wait');
  const scale = def?.scale ?? 1, px = Math.round(size * scale);
  if (def && !ready) return <span className="logo-plate skel" title={title} />;
  const url = def ? dataUrl!(def.file) : null;
  if (!url || state === 'bad') {
    // generic fallback: a neutral disc with the ticker, clearly not a logo
    let hue = 0; for (const ch of letters) hue = (hue * 31 + ch.charCodeAt(0)) % 360;
    return <span className="logo-plate" style={{ background: `hsl(${hue} 22% 46%)`, boxShadow: 'none' }} title={title} data-fallback="">
      <span className="logo-letters" style={{ fontSize: Math.max(8, size * (letters.length > 4 ? 0.21 : letters.length > 3 ? 0.25 : 0.3)) }}>{letters.slice(0, 5)}</span></span>;
  }
  const plate = def!.plate && def!.plate !== 'auto' ? def!.plate : undefined;
  return <span className={`logo-plate ${state === 'wait' ? 'skel' : ''}`} style={plate ? { background: plate } : scale === 1 && state === 'ok' ? { boxShadow: 'none' } : undefined} title={title}>
    <img src={url} alt="" width={px} height={px} style={{ width: `${scale * 100}%`, height: `${scale * 100}%` }} decoding="async" draggable={false} data-ok={state === 'ok' ? '' : undefined}
      ref={(el) => { if (el?.complete && el.naturalWidth > 0 && state === 'wait') setState('ok'); }} onLoad={() => setState('ok')} onError={() => setState('bad')} /></span>;
}

/** A network's real logo. Decorative by default (the name is written next to it); pass `label` where it stands alone. */
export function NetworkIcon({ net, size = 18, label, className = '' }: { net: string; size?: number; label?: string; className?: string }) {
  return <span className={`logo ${className}`} style={{ width: size, height: size }} role={label ? 'img' : undefined} aria-label={label} aria-hidden={label ? undefined : true}>
    <Plate def={NETWORK_ICONS[net]} size={size} letters={net.slice(0, 2).toUpperCase()} /></span>;
}

/** An asset's real logo, sizes 20–96, with the network badge when it is needed to tell two deployments apart. */
export function AssetIcon({ sym, net, size = 44, ring }: { sym: string; net?: string; size?: number; ring?: string }) {
  const on = net ?? ASSET_ICONS[sym]?.only;   // a single-network representation (BTCB, BTC.b, WBNB…) always carries its network
  const badge = needsBadge(sym, on) ? Math.max(13, Math.round(size * 0.4)) : 0;
  return <span className="logo" style={{ width: size, height: size, ...(ring ? { ['--ring' as never]: ring } : {}) }} aria-hidden="true" data-asset={sym} data-net={badge ? on : undefined}>
    <Plate def={ASSET_ICONS[sym]} size={size} letters={sym} />
    {badge > 0 && <span className="logo-badge" style={{ width: badge, height: badge }}><NetworkIcon net={on!} size={badge} /></span>}
  </span>;
}

const VENUE_ALIAS: Record<string, string> = { hl: 'hyperliquid', 'hyperliquid-testnet': 'hyperliquid' };
export function VenueIcon({ venue, size = 20, className = '' }: { venue: string; size?: number; className?: string }) {
  const id = VENUE_ALIAS[venue.toLowerCase()] ?? venue.toLowerCase();
  return <span className={`logo ${className}`} style={{ width: size, height: size }} aria-hidden="true"><Plate def={VENUE_ICONS[id]} size={size} letters={venue.slice(0, 2).toUpperCase()} /></span>;
}
export function ProviderIcon({ provider, size = 20, className = '' }: { provider: string; size?: number; className?: string }) {
  const id = provider.toLowerCase();
  return <span className={`logo ${className}`} style={{ width: size, height: size }} aria-hidden="true"><Plate def={PROVIDER_ICONS[id]} size={size} letters={provider.slice(0, 2).toUpperCase()} /></span>;
}
